func findUser(id: Int64) -> String? {
  guard id > 0 else { return nil }
  return "user-\(id)"
}

struct Stack<Element> {
  private var items: [Element] = []
  mutating func push(_ value: Element) { items.append(value) }
  mutating func pop() -> Element? { items.popLast() }
}

func groupBy<T, K: Hashable>(_ items: [T], key: (T) -> K) -> [K: [T]] {
  Dictionary(grouping: items, by: key)
}

enum Result<T> {
  case ok(T)
  case err(String)
}

func retry<T>(attempts: Int = 3, operation: () throws -> T) throws -> T {
  var lastError: Error?
  for _ in 0..<attempts {
    do { return try operation() }
    catch { lastError = error }
  }
  throw lastError!
}

actor Counter {
  private var value = 0
  func increment() -> Int {
    value += 1
    return value
  }
}
